contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint256 burnAmount) public payable {
        // ensure this contract is the owner by relying on constructor-deployed c: the checker deploys c with owner = deployer (InvMutTest), per problem statement
        // read before-values
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        // attempt burn as this contract
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        // If call reverted then both totalSupply and balance must be unchanged; otherwise both decreased by exactly burnAmount
        assert(reverted ? (afterTotal == beforeTotal && afterBal == beforeBal) : (afterTotal + burnAmount == beforeTotal && afterBal + burnAmount == beforeBal));
    }
}

